SELECT DISTINCT c.DESCRIPTION, ap.ITEM, ap."PREVALENCE RATE"
FROM conditions c JOIN all_prevalences ap ON lower(ap.ITEM)=lower(c.DESCRIPTION)
WHERE c.START='2014-05-09';

SELECT c.DESCRIPTION, p."PREVALENCE RATE"
FROM conditions c LEFT JOIN all_prevalences p ON p.ITEM=c.DESCRIPTION
WHERE c.START='2014-05-09';

SELECT ITEM, "PREVALENCE RATE"
FROM all_prevalences
WHERE ITEM LIKE '%Neuropathy due to type 2 diabetes mellitus%';

SELECT START, DESCRIPTION
FROM conditions
WHERE START = '2014-05-09' OR START = '5/9/2014';

SELECT first, last
FROM patients
WHERE first LIKE '%Joe%' OR last LIKE '%Homenick%';

